html:
{% set company = frappe.get_doc("Company", doc.company) %}
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <style>
        @page {
            size: A4;
            margin: 15mm;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: Arial, sans-serif;
            font-size: 11pt;
            color: #000;
            line-height: 1.4;
        }

        .container {
            width: 100%;
            padding: 20px;
        }

        .header {
            margin-bottom: 30px;
        }

        .header img {
            height: 60px;
        }

        .title {
            font-size: 16pt;
            font-weight: bold;
            border-bottom: 2px solid #000;
            padding-bottom: 8px;
            margin: 20px 0 15px 0;
        }

        .subtitle {
            font-weight: bold;
            margin-bottom: 20px;
        }

        .page-number {
            text-align: right;
            margin-bottom: 15px;
            font-size: 10pt;
        }

        .main-table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
            font-size: 9pt;
        }

        .main-table th {
            background-color: #f0f0f0;
            border: 1px solid #000;
            padding: 8px;
            font-weight: bold;
            text-align: center;
            vertical-align: middle;
        }

        .main-table td {
            border: 1px solid #000;
            padding: 6px 8px;
            vertical-align: top;
        }

        .main-table td.right-align {
            text-align: right;
        }

        .main-table td.center-align {
            text-align: center;
        }

        .main-table tr.total-row {
            font-weight: bold;
        }

        .main-table tr.total-row td {
            background-color: #f9f9f9;
        }

        .certification {
            margin-top: 80px;
            position: relative;
        }

        .certification p {
            display: inline-block;
        }

        .stamp-image {
            display: inline-block;
            margin-left: 30px;
            vertical-align: middle;
        }

        .stamp-image img {
            height: 70px;
        }

        .signature-section {
            margin-top: 60px;
            font-weight: bold;
        }

        .footer {
            text-align: center;
            margin-top: 80px;
            font-size: 8pt;
            line-height: 1.6;
        }

        .footer p {
            margin: 0;
        }
    </style>
</head>
<body>
<div class="container">
    <!-- Header with logo -->
    <div class="header">
        {% if company.company_logo %}
        <img src="{{ company.company_logo }}" alt="Company Logo">
        {% endif %}
    </div>

    <!-- Title -->
    <div class="title">HS Code Classification</div>

    <!-- Subtitle -->
    <div class="subtitle">Dubai Ports and Customs Free Zone Corporation</div>


    <!-- Main classification table -->
    <table class="main-table">
        <thead>
            <tr>
                <th style="width: 12%;">HTS Code</th>
                <th style="width: 30%;">Material Description</th>
                <th style="width: 10%;">Country of Origin</th>
                <th style="width: 8%;">Package Type</th>
                <th style="width: 8%;">Package Qty</th>
                <th style="width: 10%;">Weight</th>
                <th style="width: 10%;">Currency Type</th>
                <th style="width: 12%;">Currency Value</th>
            </tr>
        </thead>
        <tbody>
            {% set total_packages = 0 %}
            {% set total_weight = 0 %}
            {% set total_value = 0 %}

            {% for item in doc.items %}
            <tr>
                <td class="center-align">{{ item.hs_code }}</td>
                <td>{{ item.item_name or item.description or "" }}</td>
                <td class="center-align">{{ item.country_of_origin or "" }}</td>
                <td class="center-align">{{ item.package_type or "EA" }}</td>
                <td class="right-align">{{ item.qty or 0 }}</td>
                <td class="right-align">{{ "%.4f"|format(item.weight_per_unit or item.total_weight or 0) }}</td>
                <td class="center-align">{{ item.currency or doc.currency or "USD" }}</td>
                <td class="right-align">{{ "{:,.1f}".format(item.amount or 0) }}</td>
            </tr>

            {% set total_packages = total_packages + (item.qty or 0) %}
            {% set total_weight = total_weight + (item.weight_per_unit or item.total_weight or 0) %}
            {% set total_value = total_value + (item.amount or 0) %}
            {% endfor %}

            <!-- Total row -->
            <tr class="total-row">
                <td colspan="4" class="right-align">Total :</td>
                <td class="right-align">{{ total_packages|int }}</td>
                <td class="right-align">{{ total_weight|int }}</td>
                <td></td>
                <td class="right-align">{{ "{:,.2f}".format(total_value) }}</td>
            </tr>
        </tbody>
    </table>

    <!-- Certification section -->
    <div class="certification">
        <p>I certify the information above is correct</p>
        <div class="stamp-image">
            {% if company.company_logo %}
            <img src="{{ company.company_logo }}" alt="Stamp">
            {% endif %}
        </div>
    </div>

    <!-- Signature section -->
    <div class="signature-section">
        <p>Consignee Signature and Stamp</p>
    </div>

    <!-- Footer -->
    <div class="footer">
        <p>
            PO Box 61304, Jebel Ali Free Zone, Dubai, UAE Tel:+941 4 8837838, Fax:+971 4 8837930<br>
            Email:aptec@emirates.net.ae &nbsp;&nbsp; website:www.apteconline.com
        </p>
    </div>
</div>
</body>
</html>
